export const GLOSSARY_SHARD = Object.freeze({"satoshi":{"slug":"satoshi","cat":"basics","en":"Satoshi (sats)","contentLocale":"id","term":"Satoshi (sats)","aka":["sats","sat"],"short":"Satoshi atau sats adalah satuan terkecil Bitcoin, di mana 1 BTC sama dengan 100.000.000 satoshi.","body":[["Nama satuan ini diambil dari Satoshi Nakamoto, pencipta ",["Bitcoin","bitcoin"],". Karena satu BTC bernilai besar, banyak orang lebih nyaman menghitung dalam sats. Misalnya, 0,001 BTC sama dengan 100.000 sats, angka yang lebih mudah dibaca bagi pemula."],"Satoshi juga dipakai untuk menghitung biaya transaksi di jaringan Bitcoin, biasanya dalam satuan sats per vbyte. Saat jaringan ramai, biaya per vbyte naik, dan transaksi dengan biaya lebih tinggi cenderung diproses lebih dulu.",["Di exchange, Anda biasanya tetap melihat jumlah BTC dalam desimal. Namun memahami sats membantu Anda membaca ",["biaya penarikan","withdrawal-fee"],", menghitung pembelian rutin kecil, dan menghindari salah ketik jumlah nol di belakang koma."]],"example":["Misalkan Anda membeli BTC rutin Rp100.000 setiap minggu saat harga BTC Rp1.250.000.000. Setiap pembelian menghasilkan 0,00008 BTC, atau 8.000 sats. Setelah 10 minggu dengan harga yang sama, Anda mengumpulkan 80.000 sats, atau 0,0008 BTC. Jika biaya penarikan ke ",["dompet pribadi","non-custodial-wallet"]," ditetapkan 2.000 sats, Anda akan menerima 78.000 sats di dompet."],"mistakes":["Salah menghitung jumlah nol, misalnya mengira 0,0001 BTC sama dengan 1.000 sats, padahal 10.000 sats.","Menarik jumlah yang sangat kecil sehingga biaya penarikan memakan sebagian besar saldo.","Mengira satoshi adalah koin lain yang terpisah dari Bitcoin."],"faq":[{"q":"Berapa satoshi dalam 1 Bitcoin?","a":"Satu Bitcoin sama dengan 100.000.000 satoshi. Jadi 1 satoshi adalah 0,00000001 BTC."},{"q":"Apakah bisa membeli satoshi?","a":"Ya, saat Anda membeli pecahan kecil BTC di exchange, sebenarnya Anda membeli sejumlah satoshi. Minimum pembelian tergantung aturan masing-masing exchange."}],"title":"Apa itu satoshi (sats)? Satuan terkecil Bitcoin","description":"Arti satoshi atau sats, cara mengonversi BTC ke sats, dan kenapa satuan ini berguna untuk biaya serta pembelian rutin.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin."],["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) adalah strategi membeli aset dengan nominal tetap secara berkala, misalnya setiap minggu atau bulan, tanpa memedulikan harga saat itu."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["cryptocurrency","Cryptocurrency (aset kripto)","Cryptocurrency atau aset kripto adalah aset digital yang dicatat di blockchain dan diamankan dengan kriptografi, sehingga bisa dikirim antarpengguna tanpa bank sebagai perantara."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Satu bitcoin harganya segitu. Apakah saya masih bisa beli sedikit?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"fomo":{"slug":"fomo","cat":"basics","en":"FOMO","contentLocale":"id","term":"FOMO (fear of missing out)","aka":["fear of missing out","takut ketinggalan"],"short":"FOMO atau fear of missing out adalah rasa takut ketinggalan keuntungan yang mendorong trader membeli secara impulsif setelah harga sudah naik tajam.","body":["FOMO biasanya muncul saat sebuah koin naik puluhan persen dalam sehari, teman pamer untung, atau grup Telegram ramai dengan tangkapan layar profit. Keputusan diambil berdasarkan emosi, bukan rencana, dan sering terjadi tepat di dekat puncak harga.",["Dampaknya bisa berat. Trader yang FOMO cenderung membeli dengan ",["market order","market-order"]," di harga tinggi, memakai ",["ukuran posisi","position-sizing"]," terlalu besar, atau menambah ",["leverage","leverage"],". Ketika harga berbalik, mereka panik menjual, sehingga membeli mahal dan menjual murah."],["Cara mengendalikan FOMO adalah membuat aturan sebelum masuk pasar: berapa persen dana per transaksi, di mana ",["stop loss","stop-loss"],", dan apa alasan masuk. Jika Anda ketinggalan satu kenaikan, ingat bahwa pasar selalu menyediakan peluang lain."]],"example":["Misalkan sebuah token naik dari 0,20 ke 0,50 ",["USDT","usdt"]," dalam dua hari, kenaikan 150%. Anda membeli 600 USDT di 0,50 karena takut ketinggalan, sehingga mendapat 1.200 token. Keesokan harinya harga turun ke 0,35 USDT, dan posisi Anda bernilai 420 USDT, rugi 180 USDT atau 30%. Pembeli awal di 0,20 masih untung 75% di harga yang sama."],"mistakes":["Masuk dengan seluruh dana setelah melihat koin naik 100% dalam sehari.","Mengikuti sinyal grup Telegram tanpa memahami alasan dan risiko transaksinya.","Tidak memasang stop loss karena yakin harga akan terus naik."],"faq":[{"q":"Apa arti FOMO dalam trading kripto?","a":"FOMO adalah dorongan emosional untuk membeli karena takut kehilangan kesempatan untung, biasanya setelah harga sudah naik banyak."},{"q":"Bagaimana cara menghindari FOMO?","a":"Tetapkan aturan ukuran posisi dan titik keluar sebelum membeli, gunakan limit order di harga rencana, dan kurangi paparan ke grup yang terus memamerkan profit."}],"title":"Apa itu FOMO di kripto? Arti dan cara menghindarinya","description":"Arti FOMO atau fear of missing out dalam trading kripto, dampaknya pada keputusan, dan cara membuat aturan agar tidak impulsif.","related":[["fud","FUD (fear, uncertainty, doubt)","FUD adalah singkatan dari fear, uncertainty, and doubt, yaitu informasi atau rumor negatif yang menimbulkan rasa takut dan ragu sehingga mendorong orang menjual aset."],["bull-market","Bull market (pasar bullish)","Bull market adalah periode ketika harga aset di pasar cenderung naik secara berkelanjutan selama berminggu-minggu hingga bertahun-tahun, disertai sentimen optimis dan minat beli yang tinggi."],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."],["fear-and-greed-index","Fear and Greed Index (indeks ketakutan dan keserakahan)","Fear and Greed Index adalah indikator sentimen pasar kripto berskala 0 sampai 100, di mana angka rendah menunjukkan ketakutan ekstrem dan angka tinggi menunjukkan keserakahan ekstrem."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Tentukan berapa banyak kerugian sebelum memutuskan berapa banyak yang dibeli"},"coin":null,"tool":null,"cta":false},"wash-trading":{"slug":"wash-trading","cat":"trading","en":"Wash trading","contentLocale":"id","term":"Wash trading","aka":["volume palsu","transaksi semu"],"short":"Wash trading adalah praktik membeli dan menjual aset kepada diri sendiri atau pihak yang bekerja sama untuk menciptakan kesan volume dan aktivitas pasar yang sebenarnya tidak ada.","body":["Dalam wash trading, kepemilikan aset sebenarnya tidak berpindah ke pihak lain. Akun A menjual ke akun B, lalu B menjual kembali ke A, dan keduanya dikendalikan orang yang sama. Hasilnya, volume terlihat besar padahal tidak ada minat beli atau jual yang nyata.",["Tujuannya macam-macam: membuat token terlihat ramai agar menarik pembeli, menaikkan peringkat exchange di situs data, atau memenuhi syarat listing dan kampanye. Di pasar saham, praktik ini dilarang secara tegas. Di kripto, pengawasannya berbeda-beda per negara dan per exchange, dan di ",["NFT","nft"]," pun sempat marak."],["Bagi Anda, dampaknya nyata: volume palsu memberi gambaran ",["likuiditas","liquidity"]," yang salah. Anda mungkin masuk dengan keyakinan bisa keluar kapan saja, lalu mendapati ",["order book","order-book"]," sebenarnya tipis."]],"example":["Sebuah token baru menampilkan ",["volume 24 jam","trading-volume"]," senilai 8 juta ",["USDT","usdt"],". Namun saat Anda membuka order book, total order beli dalam rentang 2% di bawah harga hanya sekitar 6.000 USDT. Artinya, volume harian lebih dari 1.300 kali lipat kedalaman pasar di sekitar harga. Rasio sejauh itu adalah tanda peringatan: jika Anda membeli 10.000 USDT lalu ingin menjual kembali, harga bisa jatuh jauh sebelum seluruh posisi Anda terjual."],"mistakes":["Memilih token hanya karena muncul di daftar volume tertinggi.","Tidak membandingkan volume dengan kedalaman order book dan jumlah transaksi nyata.","Mengira wash trading hanya terjadi di exchange kecil, padahal bisa juga terjadi pada pasangan tertentu di platform mana pun."],"faq":[{"q":"Bagaimana cara mendeteksi wash trading?","a":"Waspadai volume besar dengan order book tipis, transaksi berulang dengan ukuran sama, dan volume yang tidak sejalan dengan exchange lain. Data on-chain juga bisa menunjukkan dompet yang saling berputar."},{"q":"Apakah wash trading ilegal?","a":"Di banyak yurisdiksi, wash trading dianggap manipulasi pasar dan dilarang. Aturan untuk aset kripto berbeda di tiap negara, tetapi praktik ini umumnya dilarang oleh aturan exchange yang serius."}],"title":"Apa itu wash trading? Arti dan cara mengenali volume palsu","description":"Kenali wash trading di kripto: cara kerja volume palsu, kenapa berbahaya bagi trader, dan tanda-tanda yang perlu Anda periksa.","related":[["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["proof-of-reserves","Proof of reserves (bukti cadangan)","Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree."],["market-maker","Market maker","Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread."]],"lesson":null,"coin":null,"tool":"/exchanges","cta":false},"whale":{"slug":"whale","cat":"trading","en":"Whale","contentLocale":"id","term":"Whale (paus kripto)","aka":["paus","whale kripto","big player"],"short":"Whale adalah sebutan untuk individu atau entitas yang memegang aset kripto dalam jumlah sangat besar sehingga transaksinya berpotensi menggerakkan harga pasar.","body":[["Tidak ada batas resmi untuk disebut whale. Di ",["Bitcoin","bitcoin"],", alamat yang memegang lebih dari 1.000 BTC sering dipakai sebagai patokan, tetapi untuk token kecil, beberapa ratus ribu dolar saja sudah cukup besar. Whale bisa berupa investor awal, dana investasi, exchange, atau tim proyek."],["Karena ",["blockchain","blockchain"]," bersifat publik, pergerakan dompet besar bisa dipantau lewat ",["analisis on-chain","on-chain-analysis"],". Transfer besar dari ",["dompet pribadi","non-custodial-wallet"]," ke exchange sering dibaca sebagai kemungkinan akan dijual, sedangkan penarikan dari exchange dibaca sebagai penyimpanan jangka panjang. Namun, ini hanya petunjuk, bukan kepastian."],["Satu alamat besar juga belum tentu milik satu orang. ",["Dompet exchange","custodial-wallet"],", kustodian, dan ",["kontrak pintar","smart-contract"]," sering terlihat seperti whale, jadi selalu cek label alamat sebelum menyimpulkan."]],"example":"Misalkan sebuah token punya order beli total 400.000 USDT dalam rentang 3% di bawah harga 2,00 USDT. Seorang whale menjual 500.000 token, senilai sekitar 1 juta USDT, dengan market order. Order itu menghabiskan seluruh order beli dalam rentang 3% lalu terus turun, sehingga harga bisa jatuh ke sekitar 1,85 atau lebih rendah. Trader yang memasang stop loss di 1,95 ikut terjual di harga yang lebih buruk dari rencana.","mistakes":["Langsung menjual setiap kali ada notifikasi transfer besar ke exchange tanpa mengecek siapa pemilik alamat.","Mengikuti whale secara buta, padahal tujuan dan jangka waktunya bisa sangat berbeda dengan Anda.","Mengabaikan konsentrasi kepemilikan saat membeli token kecil yang sebagian besar suplainya dipegang segelintir dompet."],"faq":[{"q":"Bagaimana cara melacak pergerakan whale?","a":"Gunakan block explorer dan platform analitik on-chain yang memberi label pada alamat besar dan arus masuk-keluar exchange. Perhatikan konteks, bukan hanya angka transfer."},{"q":"Apakah whale bisa memanipulasi harga?","a":"Whale bisa menggerakkan harga, terutama di pasar dengan likuiditas tipis. Praktik seperti spoofing dan pump and dump termasuk manipulasi dan dilarang di banyak yurisdiksi."}],"title":"Apa itu whale di kripto? Arti dan pengaruhnya ke harga","description":"Kenali whale atau paus kripto: siapa mereka, cara melacak dompet besar on-chain, dan pengaruh transaksi mereka terhadap harga.","related":[["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."],["exchange-netflow","Arus masuk dan keluar bursa (exchange netflow)","Exchange netflow adalah selisih antara jumlah kripto yang masuk ke dompet bursa dan yang keluar dari bursa dalam periode tertentu, dipakai untuk membaca niat jual atau simpan para pemegang."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"margin-call":{"slug":"margin-call","cat":"derivatives","en":"Margin call","contentLocale":"id","term":"Margin call","aka":["peringatan margin","panggilan margin"],"short":"Margin call adalah peringatan bahwa jaminan di akun atau posisi Anda sudah mendekati batas minimum, sehingga Anda perlu menambah margin atau mengurangi posisi agar tidak dilikuidasi.","body":["Di pasar tradisional, margin call berarti broker meminta Anda menyetor dana tambahan dalam waktu tertentu. Di exchange kripto, prosesnya jauh lebih cepat dan otomatis. Anda biasanya menerima notifikasi lewat aplikasi atau email saat rasio margin melewati ambang tertentu, tetapi exchange tidak wajib menunggu Anda bertindak.",["Jika harga terus bergerak melawan posisi, ",["likuidasi","liquidation"]," bisa terjadi beberapa detik setelah peringatan, terutama saat ",["volatilitas","volatility"]," tinggi. Karena itu, notifikasi margin call sebaiknya dianggap sebagai sinyal terakhir, bukan bagian dari rencana."],"Pilihan Anda saat menerima margin call: menambah margin, menutup sebagian posisi, atau menutup seluruh posisi. Menambah margin berulang kali ke posisi yang terus rugi sering hanya memperbesar kerugian akhir."],"example":["Anda memegang short ",["BTC","bitcoin"]," senilai 12.000 ",["USDT","usdt"]," dengan margin 1.200 USDT di ",["isolated margin","isolated-margin"],". Exchange mengirim peringatan saat rasio margin mencapai 80%. Harga naik 7%, sehingga kerugian Anda 840 USDT dan sisa margin 360 USDT. ",["Maintenance margin","maintenance-margin"]," posisi ini misalnya 60 USDT. Jika harga naik sekitar 2,5% lagi, atau 300 USDT kerugian tambahan, posisi akan dilikuidasi. Menambah 600 USDT margin akan memberi ruang sekitar 5% lagi."],"mistakes":["Mengandalkan notifikasi margin call sebagai pengganti stop loss.","Terus menambah margin ke posisi rugi tanpa alasan selain berharap harga berbalik.","Mematikan notifikasi aplikasi exchange sehingga peringatan tidak terlihat."],"faq":[{"q":"Apakah exchange kripto memberi waktu setelah margin call?","a":"Umumnya tidak ada tenggat seperti di broker tradisional. Likuidasi berjalan otomatis begitu ekuitas posisi turun di bawah maintenance margin."},{"q":"Bagaimana cara menghindari margin call?","a":"Gunakan leverage rendah, hitung ukuran posisi dari jarak stop loss, dan pasang stop loss yang tereksekusi jauh sebelum harga likuidasi."}],"title":"Apa itu margin call di kripto? Arti dan cara menghadapinya","description":"Pahami margin call di exchange kripto, kapan peringatan muncul, apa pilihan Anda, dan kenapa sebaiknya tidak mengandalkannya.","related":[["maintenance-margin","Maintenance margin (margin pemeliharaan)","Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Mengapa posisi Anda bisa ditutup sebelum margin Anda menyentuh nol?"},"coin":null,"tool":"/liquidations","cta":false},"liquidation":{"slug":"liquidation","cat":"derivatives","en":"Liquidation","contentLocale":"id","term":"Likuidasi (liquidation)","aka":["liquidation","kena likuidasi","posisi dilikuidasi","liq"],"short":"Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang.","body":[["Saat harga bergerak melawan posisi Anda, kerugian mengurangi margin. Begitu ekuitas posisi, yang dihitung dengan ",["mark price","mark-price"],", turun ke level ",["maintenance margin","maintenance-margin"],", mesin likuidasi exchange mengambil alih dan menutup posisi di pasar. Untuk posisi besar, banyak exchange melikuidasi secara bertahap."],["Jika posisi berhasil ditutup di harga yang lebih baik dari harga kebangkrutan, sisanya biasanya masuk ke ",["insurance fund","insurance-fund"],". Jika pasar bergerak terlalu cepat dan dana tidak cukup, insurance fund menutup selisihnya, dan dalam kondisi ekstrem exchange bisa memakai ",["auto-deleveraging","auto-deleveraging"],". Biaya likuidasi dan rinciannya berbeda tiap exchange."],"Likuidasi massal juga menggerakkan pasar. Ketika banyak posisi long dilikuidasi sekaligus, penjualan paksa bisa mendorong harga turun lebih jauh dan memicu likuidasi berikutnya, yang dikenal sebagai efek berantai."],"example":["Anda membuka long ",["ETH","ethereum"]," senilai 9.000 ",["USDT","usdt"]," di harga 3.000, setara 3 ETH, dengan leverage 15x di isolated margin. Margin awal Anda 600 USDT. Misalkan maintenance margin 0,5%, yaitu 45 USDT. Likuidasi terjadi saat kerugian mencapai sekitar 555 USDT, atau 185 USDT per ETH. Jadi harga likuidasi sekitar 2.815, hanya sekitar 6,2% di bawah harga masuk. Jika itu terjadi, hampir seluruh 600 USDT hilang."],"mistakes":["Tidak mengecek harga likuidasi sebelum membuka posisi.","Menaruh stop loss di bawah harga likuidasi sehingga stop loss tidak pernah sempat bekerja.","Mengira likuidasi dipicu oleh harga transaksi terakhir, padahal kebanyakan exchange memakai mark price."],"faq":[{"q":"Apakah saya kehilangan semua uang jika dilikuidasi?","a":"Di isolated margin, Anda kehilangan margin posisi itu. Di cross margin, likuidasi bisa menghabiskan seluruh saldo akun futures. Saldo di akun spot biasanya tidak tersentuh kecuali Anda memakai akun terpadu."},{"q":"Bagaimana cara menghindari likuidasi?","a":"Gunakan leverage rendah, tentukan ukuran posisi dari jarak stop loss, dan pastikan stop loss tereksekusi jauh sebelum harga likuidasi."},{"q":"Apa itu likuidasi berantai?","a":"Saat banyak posisi dilikuidasi bersamaan, penjualan atau pembelian paksa mendorong harga ke arah yang sama dan memicu likuidasi posisi lain di level berikutnya."}],"title":"Apa itu likuidasi di kripto? Arti dan cara menghindarinya","description":"Pahami likuidasi di futures kripto: kapan posisi ditutup paksa, peran maintenance margin dan mark price, serta cara menghindarinya.","related":[["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin."],["maintenance-margin","Maintenance margin (margin pemeliharaan)","Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda."],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["insurance-fund","Insurance fund (dana asuransi)","Insurance fund adalah cadangan dana milik exchange futures yang dipakai untuk menutup kerugian ketika posisi yang dilikuidasi ditutup di harga lebih buruk dari harga kebangkrutannya, sehingga trader lain tidak ikut menanggung."],["auto-deleveraging","Auto-deleveraging (ADL)","Auto-deleveraging adalah mekanisme darurat exchange futures yang otomatis menutup sebagian posisi trader yang sedang untung untuk menutup kerugian dari posisi bangkrut, ketika insurance fund tidak cukup."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?"},"coin":null,"tool":"/liquidations","cta":false},"liquidation-price":{"slug":"liquidation-price","cat":"derivatives","en":"Liquidation price","contentLocale":"id","term":"Harga likuidasi (liquidation price)","aka":["liquidation price","harga liq","titik likuidasi"],"short":"Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin.","body":[["Exchange menampilkan harga likuidasi saat Anda membuka posisi dan memperbaruinya selama ",["posisi terbuka","open-interest"],". Untuk posisi long, harga likuidasi berada di bawah harga masuk; untuk short, berada di atasnya. Semakin tinggi ",["leverage","leverage"],", semakin dekat harga likuidasi dengan harga masuk."],["Rumus sederhana untuk ",["isolated margin","isolated-margin"]," kira-kira: jarak ke ",["likuidasi","liquidation"]," dalam persen sama dengan 1 dibagi leverage dikurangi persentase ",["maintenance margin","maintenance-margin"],". Angka di aplikasi bisa sedikit berbeda karena biaya, funding yang sudah dibayar, dan tingkatan risiko. Di ",["mode cross","cross-margin"],", harga likuidasi bergantung pada seluruh saldo dan posisi lain, sehingga terus berubah."],"Harga likuidasi dibandingkan dengan mark price, bukan harga transaksi terakhir. Lonjakan singkat di satu exchange tidak selalu memicu likuidasi, tetapi pergerakan nyata di pasar indeks akan memicunya."],"example":"Anda short SOL di 150 USDT dengan leverage 20x di isolated margin, dan maintenance margin 1%. Jarak ke likuidasi kira-kira 1/20 - 1% = 5% - 1% = 4%. Jadi harga likuidasi sekitar 150 x 1,04 = 156 USDT. Kenaikan hanya 6 USDT sudah cukup untuk menutup posisi Anda. Jika Anda menurunkan leverage ke 5x, jaraknya menjadi 20% - 1% = 19%, sehingga harga likuidasi sekitar 178,5 USDT.","mistakes":["Menganggap harga likuidasi di aplikasi tetap, padahal bisa bergeser karena funding, biaya, atau perubahan margin.","Memasang stop loss lebih jauh dari harga likuidasi.","Lupa bahwa di mode cross, membuka posisi lain atau menarik dana mengubah harga likuidasi."],"faq":[{"q":"Bagaimana cara menjauhkan harga likuidasi?","a":"Turunkan leverage, tambah margin pada posisi isolated, atau kurangi ukuran posisi. Ketiganya membuat jarak antara harga masuk dan likuidasi lebih lebar."},{"q":"Kenapa posisi saya dilikuidasi padahal harga di grafik belum menyentuh harga likuidasi?","a":"Grafik biasanya menampilkan harga transaksi terakhir, sedangkan likuidasi memakai mark price. Biaya dan funding yang terpotong juga bisa menggeser harga likuidasi sedikit."}],"title":"Apa itu harga likuidasi? Arti dan cara menghitungnya","description":"Pelajari harga likuidasi di futures kripto, rumus perkiraannya, pengaruh leverage dan maintenance margin, serta cara menjauhkannya.","related":[["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut."],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["maintenance-margin","Maintenance margin (margin pemeliharaan)","Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?"},"coin":null,"tool":"/liquidations","cta":false},"long-short-ratio":{"slug":"long-short-ratio","cat":"derivatives","en":"Long/short ratio","contentLocale":"id","term":"Rasio long/short (long/short ratio)","aka":["long short ratio","rasio long short","LSR"],"short":"Rasio long/short adalah perbandingan antara jumlah akun atau nilai posisi long dan short di pasar futures, dipakai untuk membaca sentimen trader terhadap sebuah aset.","body":["Exchange seperti Binance, OKX, dan Bybit mempublikasikan beberapa versi rasio ini. Ada yang menghitung jumlah akun yang long dibanding short, ada yang menghitung nilai posisi, dan ada yang khusus untuk top trader dengan saldo besar. Ketiganya bisa memberi gambaran yang berbeda, jadi baca definisinya.",["Perlu diingat, setiap ",["kontrak futures","futures-contract"]," selalu punya pembeli dan penjual, sehingga total ",["posisi long dan short","long-and-short"]," dalam nilai selalu sama. Rasio akun berbeda dari 1 karena jumlah orangnya berbeda: misalnya banyak akun kecil long, sementara sedikit akun besar short."],["Banyak trader membaca rasio ini secara kontrarian. Jika mayoritas akun ritel long berlebihan, pasar rentan terhadap long squeeze. Namun rasio ini hanya satu petunjuk dan sebaiknya dibaca bersama ",["funding rate","funding-rate"],", ",["open interest","open-interest"],", dan struktur harga."]],"example":["Sebuah exchange menampilkan rasio akun long/short ",["ETH","ethereum"]," sebesar 2,5. Artinya, dari setiap 100 akun yang punya posisi ETH, sekitar 71 akun long dan 29 akun short, karena 71 dibagi 29 kira-kira 2,45. Namun karena nilai total long dan short harus sama, 29 akun short itu rata-rata memegang posisi sekitar 2,5 kali lebih besar daripada akun long. Ini sering menandakan akun besar berada di sisi short."],"mistakes":["Menganggap rasio long/short di atas 1 berarti harga pasti naik.","Tidak membedakan rasio akun, rasio posisi, dan rasio top trader.","Membandingkan rasio dari exchange berbeda yang memakai metode perhitungan berbeda."],"faq":[{"q":"Apa arti rasio long/short di atas 1?","a":"Lebih banyak akun atau posisi yang long dibanding short, tergantung definisinya. Ini menunjukkan sentimen, bukan arah harga yang pasti."},{"q":"Kenapa rasio long/short bisa tinggi padahal harga turun?","a":"Banyak trader ritel cenderung membeli saat harga turun, sementara akun besar memegang short. Karena itu rasio akun yang tinggi kadang justru muncul di tren turun."}],"title":"Apa itu rasio long/short di kripto? Arti dan cara membacanya","description":"Pahami rasio long/short di futures kripto: jenis-jenis rasio, cara menghitung, dan cara membacanya bersama funding rate dan OI.","related":[["open-interest","Open interest (OI)","Open interest adalah total nilai atau jumlah kontrak futures dan opsi yang masih terbuka dan belum ditutup atau diselesaikan pada suatu waktu."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["long-and-short","Posisi long dan short","Posisi long adalah posisi yang untung saat harga naik, sedangkan posisi short adalah posisi yang untung saat harga turun; keduanya bisa dibuka di futures maupun margin trading."],["short-squeeze","Short squeeze","Short squeeze adalah kenaikan harga yang cepat dan tajam karena banyak trader short terpaksa menutup posisi dengan membeli kembali aset, baik karena stop loss maupun likuidasi, sehingga mendorong harga naik lebih jauh."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"anti-phishing-code":{"slug":"anti-phishing-code","cat":"wallets-security","en":"Anti-phishing code","contentLocale":"id","term":"Kode anti-phishing","aka":["anti-phishing code","kode antiphishing"],"short":"Kode anti-phishing adalah kata atau kode rahasia yang Anda tetapkan di akun exchange, lalu dicantumkan di setiap email resmi exchange agar Anda bisa membedakannya dari email palsu.","body":["Penipu sering mengirim email yang tampilannya persis seperti email exchange, misalnya peringatan login mencurigakan atau permintaan verifikasi ulang. Logo, warna, dan bahasa bisa ditiru dengan mudah. Yang tidak bisa mereka tiru adalah kode yang hanya Anda dan exchange ketahui.","Setelah Anda mengaktifkan kode anti-phishing di menu keamanan, exchange menampilkannya di email resmi, dan di beberapa platform juga di notifikasi atau SMS. Jika ada email yang mengaku dari exchange tetapi tidak memuat kode itu, anggap email tersebut palsu dan jangan klik tautannya.",["Fitur ini tersedia di banyak exchange besar seperti Binance, OKX, Bybit, dan Bitget, meski nama menu dan cakupannya bisa berbeda. Kode ini bukan pengganti ",["2FA","two-factor-authentication"],". Fungsinya hanya membantu Anda mengenali komunikasi asli, jadi tetap periksa alamat domain sebelum login."]],"example":["Anda menetapkan kode anti-phishing KopiPagi77 di exchange. Suatu malam masuk email berjudul akun Anda akan dibekukan dalam 24 jam, lengkap dengan logo dan tombol verifikasi. Anda melihat bagian atas email dan tidak menemukan KopiPagi77. Anda tidak mengklik apa pun, lalu membuka aplikasi exchange secara langsung. Di sana tidak ada pemberitahuan pembekuan. Saldo 1.200 ",["USDT","usdt"]," Anda aman karena Anda tidak memasukkan kata sandi di halaman palsu."],"mistakes":["Memakai kode yang mudah ditebak, seperti nama exchange atau nama Anda sendiri.","Membagikan tangkapan layar email yang memperlihatkan kode anti-phishing di grup publik.","Mengira email yang memuat kode pasti aman lalu tidak lagi memeriksa domain tautan."],"faq":[{"q":"Apakah kode anti-phishing sama dengan 2FA?","a":"Tidak. 2FA melindungi login dan penarikan, sedangkan kode anti-phishing membantu Anda mengenali email atau pesan resmi dari exchange."},{"q":"Bagaimana jika email tanpa kode anti-phishing meminta saya login?","a":"Abaikan tautannya. Buka aplikasi atau situs resmi exchange secara manual dan periksa apakah ada pemberitahuan yang sama di sana."}],"title":"Apa itu kode anti-phishing? Cara kerja dan manfaatnya","description":"Arti kode anti-phishing di exchange kripto, cara mengaktifkannya, dan cara memakainya untuk mengenali email palsu.","related":[["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["two-factor-authentication","Autentikasi dua faktor (2FA)","Autentikasi dua faktor (2FA) adalah lapisan keamanan yang meminta bukti kedua selain kata sandi, misalnya kode dari aplikasi autentikator atau kunci keamanan fisik, sebelum Anda bisa login atau menarik dana."],["withdrawal-whitelist","Whitelist penarikan (withdrawal whitelist)","Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan"},"coin":null,"tool":null,"cta":false},"pig-butchering-scam":{"slug":"pig-butchering-scam","cat":"wallets-security","en":"Pig-butchering scam","contentLocale":"id","term":"Penipuan pig butchering","aka":["pig butchering","penipuan investasi romansa","sha zhu pan"],"short":"Pig butchering adalah penipuan jangka panjang di mana pelaku membangun hubungan pertemanan atau asmara dengan korban, lalu membujuknya berinvestasi kripto di platform palsu sampai seluruh dana diambil.","body":["Nama ini berasal dari istilah Tiongkok yang menggambarkan babi yang digemukkan sebelum disembelih. Pelaku biasanya mulai dari pesan salah sambung, aplikasi kencan, atau grup media sosial. Selama berminggu-minggu mereka bersikap ramah, berbagi cerita hidup, lalu perlahan menyebut kesuksesannya di trading kripto.","Korban kemudian diarahkan ke situs atau aplikasi trading yang tampak profesional tetapi dikendalikan pelaku. Saldo di layar terlihat naik, dan penarikan kecil di awal sering diizinkan untuk membangun kepercayaan. Saat korban menyetor dalam jumlah besar dan mencoba menarik, muncul alasan seperti pajak, biaya verifikasi, atau akun dibekukan yang meminta setoran tambahan.","Tanda bahayanya jelas: kenalan online yang belum pernah Anda temui mengajak berinvestasi, platform yang tidak dikenal atau tidak bisa ditemukan di toko aplikasi resmi, keuntungan yang terlalu stabil, dan permintaan biaya sebelum penarikan."],"example":["Seseorang yang Anda kenal dari aplikasi kencan mengajak trading di situs yang ia sebut milik pamannya. Anda menyetor 1.000 ",["USDT","usdt"],", saldo di layar naik menjadi 1.300 USDT dalam seminggu, dan penarikan 100 USDT berhasil. Anda lalu menyetor 10.000 USDT. Saat mencoba menarik, situs meminta pajak 20% atau 2.000 USDT terlebih dahulu. Ini pola klasik: dana tidak pernah diperdagangkan, dan membayar biaya itu hanya menambah kerugian."],"mistakes":["Mempercayai platform investasi hanya karena saldo di layarnya terus naik.","Membayar pajak atau biaya pembukaan blokir agar bisa menarik dana.","Menyimpan rahasia dari keluarga karena diminta oleh kenalan online."],"faq":[{"q":"Bagaimana mengenali penipuan pig butchering?","a":"Waspadai kenalan online yang cepat akrab lalu mengarahkan Anda ke platform investasi tertentu, terutama jika platform itu meminta biaya sebelum penarikan."},{"q":"Apa yang harus dilakukan jika sudah menjadi korban?","a":"Hentikan setoran, simpan bukti chat dan TxID, lalu laporkan ke kepolisian dan exchange yang dipakai untuk mengirim dana. Waspadai juga jasa pemulihan dana yang meminta bayaran di muka, karena itu sering penipuan lanjutan."}],"title":"Apa itu penipuan pig butchering? Ciri dan cara menghindari","description":"Pelajari cara kerja penipuan pig butchering di kripto, tanda-tanda bahayanya, dan langkah yang perlu diambil jika menjadi korban.","related":[["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["rug-pull","Rug pull","Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar."],["p2p-trading","P2P trading (jual beli P2P)","P2P trading adalah jual beli kripto langsung antarpengguna di platform bursa, di mana pembayaran rupiah dilakukan lewat transfer bank atau e-wallet dan kripto penjual ditahan sistem escrow."],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya."},"coin":null,"tool":null,"cta":false},"hash-rate":{"slug":"hash-rate","cat":"onchain","en":"Hash rate","contentLocale":"id","term":"Hash rate","aka":["hashrate","daya komputasi penambangan"],"short":"Hash rate adalah total daya komputasi yang dipakai penambang untuk mengamankan blockchain proof of work seperti Bitcoin, diukur dalam jumlah tebakan hash per detik.","body":[["Dalam ",["proof of work","proof-of-work"],", penambang berlomba menebak angka yang menghasilkan hash sesuai target. Semakin banyak tebakan per detik, semakin besar peluang menemukan blok. Satuannya bertingkat: TH/s (triliun hash per detik), PH/s, hingga EH/s (exahash per detik) untuk jaringan ",["Bitcoin","bitcoin"]," saat ini."],"Hash rate tinggi berarti jaringan lebih sulit diserang, karena penyerang perlu menguasai sebagian besar daya komputasi untuk melakukan serangan 51%. Bitcoin menyesuaikan tingkat kesulitan setiap 2.016 blok, sekitar dua minggu, agar rata-rata waktu blok tetap mendekati 10 menit meski hash rate berubah.","Bagi pengamat pasar, hash rate mencerminkan kondisi penambang. Setelah halving, seperti April 2024 saat imbalan blok turun ke 3,125 BTC, penambang dengan biaya listrik mahal bisa berhenti sehingga hash rate turun sementara. Namun hash rate bukan sinyal harga langsung."],"example":"Misalkan total hash rate jaringan 600 EH/s dan Anda menjalankan mesin berkapasitas 200 TH/s. Porsi Anda adalah 200 TH/s dibagi 600.000.000 TH/s, yaitu sekitar 0,000033%. Dengan sekitar 144 blok per hari dan imbalan 3,125 BTC per blok, total imbalan harian sekitar 450 BTC. Bagian rata-rata Anda kira-kira 0,00015 BTC per hari, belum termasuk biaya transaksi dan sebelum dipotong biaya listrik serta biaya pool. Jika hash rate jaringan naik, bagian Anda mengecil.","mistakes":["Menganggap kenaikan hash rate pasti membuat harga Bitcoin naik.","Menghitung keuntungan mining tanpa memasukkan biaya listrik dan kenaikan hash rate jaringan.","Mengira hash rate berlaku untuk blockchain proof of stake seperti Ethereum saat ini."],"faq":[{"q":"Apa arti hash rate Bitcoin turun?","a":"Artinya sebagian penambang mematikan mesin, misalnya karena biaya listrik naik atau imbalan turun setelah halving. Tingkat kesulitan akan menyesuaikan sehingga waktu blok kembali mendekati 10 menit."},{"q":"Apa satuan hash rate?","a":"Satuannya hash per detik, dengan awalan seperti TH/s untuk triliun, PH/s untuk kuadriliun, dan EH/s untuk kuintiliun. Jaringan Bitcoin diukur dalam EH/s."}],"title":"Apa itu hash rate? Arti hash rate Bitcoin","description":"Pelajari arti hash rate, satuannya, hubungannya dengan keamanan jaringan Bitcoin, halving, dan penyesuaian kesulitan.","related":[["mining","Mining (penambangan kripto)","Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan."],["bitcoin-halving","Bitcoin halving","Bitcoin halving adalah peristiwa terjadwal kira-kira setiap empat tahun, atau tepatnya setiap 210.000 blok, ketika imbalan blok untuk penambang dipotong setengah."],["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"exchange-netflow":{"slug":"exchange-netflow","cat":"onchain","en":"Exchange inflows and outflows","contentLocale":"id","term":"Arus masuk dan keluar bursa (exchange netflow)","aka":["exchange netflow","exchange inflow","exchange outflow","netflow bursa"],"short":"Exchange netflow adalah selisih antara jumlah kripto yang masuk ke dompet bursa dan yang keluar dari bursa dalam periode tertentu, dipakai untuk membaca niat jual atau simpan para pemegang.","body":["Inflow adalah koin yang dikirim ke alamat bursa, sedangkan outflow adalah koin yang ditarik dari bursa. Netflow sama dengan inflow dikurangi outflow. Netflow positif berarti saldo koin di bursa bertambah, netflow negatif berarti berkurang.",["Logika umumnya: orang memindahkan koin ke bursa jika ingin menjual atau memakainya sebagai margin, dan menarik koin ke ",["dompet pribadi","non-custodial-wallet"]," untuk disimpan jangka panjang. Untuk ",["stablecoin","stablecoin"],", logikanya terbalik: inflow stablecoin besar bisa berarti ada dana siap untuk membeli."],["Hati-hati menafsirkan data ini. Bursa sering memindahkan dana antar dompet internal, menggabungkan saldo, atau memindahkan ke kustodian ETF. Label alamat dari penyedia data juga tidak selalu lengkap. Lihat tren beberapa hari dan bandingkan dengan data lain, misalnya ",["funding rate","funding-rate"]," dan volume."]],"example":["Misalkan dalam seminggu tercatat inflow ",["ETH","ethereum"]," ke bursa 300.000 ETH dan outflow 380.000 ETH. Netflow-nya minus 80.000 ETH, artinya saldo ETH di bursa berkurang. Ini sering ditafsirkan sebagai akumulasi, karena koin ditarik untuk disimpan atau di-",["staking","staking"],". Namun jika ternyata 60.000 ETH dari outflow itu adalah satu bursa yang memindahkan dana ke ",["dompet dingin","cold-wallet"]," baru yang belum diberi label, maka netflow sebenarnya hanya sekitar minus 20.000 ETH, dan sinyalnya jauh lebih lemah."],"mistakes":["Langsung menganggap inflow besar sebagai tanda harga akan turun.","Mengabaikan perpindahan dana internal bursa yang bisa mendistorsi data.","Membaca netflow stablecoin dengan logika yang sama seperti netflow BTC atau ETH."],"faq":[{"q":"Apakah netflow negatif berarti bullish?","a":"Netflow negatif sering dibaca sebagai tanda akumulasi karena koin ditarik dari bursa. Tetapi ini bukan jaminan arah harga dan bisa terdistorsi oleh perpindahan internal bursa."},{"q":"Kenapa inflow stablecoin ke bursa diperhatikan?","a":"Stablecoin yang masuk ke bursa bisa menjadi daya beli untuk aset lain. Namun dana itu juga bisa dipakai sebagai margin derivatif, bukan hanya untuk membeli spot."}],"title":"Apa itu exchange netflow? Arus masuk-keluar bursa","description":"Pahami exchange inflow, outflow, dan netflow: cara membaca arus kripto ke bursa dan jebakan dalam menafsirkan datanya.","related":[["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."],["whale","Whale (paus kripto)","Whale adalah sebutan untuk individu atau entitas yang memegang aset kripto dalam jumlah sangat besar sehingga transaksinya berpotensi menggerakkan harga pasar."],["proof-of-reserves","Proof of reserves (bukti cadangan)","Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"active-addresses":{"slug":"active-addresses","cat":"onchain","en":"Active addresses","contentLocale":"id","term":"Alamat aktif (active addresses)","aka":["active addresses","alamat aktif harian","DAA"],"short":"Alamat aktif adalah jumlah alamat blockchain unik yang mengirim atau menerima transaksi dalam periode tertentu, dipakai sebagai gambaran kasar tingkat penggunaan sebuah jaringan.","body":[["Metrik ini biasanya dihitung harian, mingguan, atau bulanan. Jika jumlah alamat aktif naik dalam waktu lama, itu bisa menandakan lebih banyak orang memakai jaringan, misalnya untuk transfer, ",["DeFi","defi"],", atau aplikasi lain."],["Namun alamat tidak sama dengan orang. Satu pengguna bisa punya banyak alamat, dan bursa bisa mengelola ribuan alamat untuk nasabahnya. Di jaringan dengan biaya sangat murah, bot dan aktivitas pemburu ",["airdrop","airdrop"]," bisa menggelembungkan angka alamat aktif tanpa ada pengguna nyata yang bertambah."],["Karena itu, bandingkan alamat aktif dengan metrik lain, seperti nilai transaksi, biaya yang dibayar pengguna, atau ",["TVL","total-value-locked"],". Bandingkan juga antarjaringan dengan hati-hati, karena cara menghitung akun di ",["Bitcoin","bitcoin"],", ",["Ethereum","ethereum"],", dan Solana berbeda."]],"example":["Misalkan sebuah jaringan ",["layer 2","layer-2"]," mencatat lonjakan alamat aktif harian dari 200.000 menjadi 900.000 dalam dua minggu, saat beredar kabar airdrop. Namun total biaya yang dibayar pengguna hanya naik dari 20.000 dolar menjadi 26.000 dolar per hari. Artinya biaya rata-rata per alamat justru turun dari 0,10 dolar menjadi sekitar 0,03 dolar. Pola ini mengarah pada banyak alamat kecil yang dibuat untuk berburu airdrop, bukan pertumbuhan penggunaan yang sebanding dengan lonjakan angka alamat."],"mistakes":["Menyamakan jumlah alamat aktif dengan jumlah pengguna nyata.","Membandingkan alamat aktif antarjaringan tanpa memperhatikan perbedaan biaya dan model akun.","Mengabaikan aktivitas bot dan pemburu airdrop yang menggelembungkan angka."],"faq":[{"q":"Apakah kenaikan alamat aktif tanda bagus?","a":"Bisa menandakan adopsi, tetapi perlu dicek apakah diikuti kenaikan nilai transaksi dan biaya. Lonjakan tanpa aktivitas ekonomi yang sebanding sering berasal dari bot atau kampanye insentif."},{"q":"Apa beda alamat aktif dan alamat baru?","a":"Alamat aktif menghitung semua alamat yang bertransaksi dalam periode itu. Alamat baru hanya menghitung alamat yang muncul pertama kali di blockchain."}],"title":"Apa itu alamat aktif? Arti active addresses kripto","description":"Pelajari arti alamat aktif di blockchain, cara memakainya untuk menilai penggunaan jaringan, dan jebakan bot.","related":[["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."],["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar."],["total-value-locked","TVL (total value locked)","TVL adalah total nilai aset kripto yang disetor ke sebuah protokol DeFi atau blockchain, dihitung dalam dolar AS, dan sering dipakai sebagai ukuran kasar seberapa besar sebuah protokol dipakai."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"fear-and-greed-index":{"slug":"fear-and-greed-index","cat":"onchain","en":"Fear and Greed Index","contentLocale":"id","term":"Fear and Greed Index (indeks ketakutan dan keserakahan)","aka":["Fear and Greed Index","indeks fear and greed","indeks ketakutan dan keserakahan"],"short":"Fear and Greed Index adalah indikator sentimen pasar kripto berskala 0 sampai 100, di mana angka rendah menunjukkan ketakutan ekstrem dan angka tinggi menunjukkan keserakahan ekstrem.","body":[["Indeks ini menggabungkan beberapa data menjadi satu angka. Versi yang paling sering dikutip untuk kripto memakai faktor seperti ",["volatilitas","volatility"],", momentum dan ",["volume perdagangan","trading-volume"],", aktivitas media sosial, dominasi ",["Bitcoin","bitcoin"],", serta tren pencarian. Penyedia yang berbeda memakai rumus berbeda, jadi angkanya bisa tidak sama."],["Pembagian umumnya: 0 sampai 24 ketakutan ekstrem, 25 sampai 49 takut, sekitar 50 netral, 51 sampai 74 serakah, dan 75 ke atas keserakahan ekstrem. Banyak trader memakainya sebagai pengingat emosi: saat semua orang serakah, risiko ",["FOMO","fomo"]," tinggi; saat semua orang takut, banyak yang menjual karena panik."],["Indeks ini bukan sinyal beli atau jual. Pasar bisa berada di zona keserakahan ekstrem selama berminggu-minggu, dan ketakutan ekstrem bisa berlanjut saat harga terus turun. Gunakan sebagai konteks bersama data lain, misalnya ",["funding rate","funding-rate"]," dan ",["open interest","open-interest"],"."]],"example":"Misalkan indeks berada di 82 dan funding rate perpetual BTC di banyak bursa naik ke 0,05% per 8 jam, jauh di atas level biasanya 0,01%. Kombinasi ini menunjukkan banyak trader memakai leverage untuk posisi long. Jika Anda berencana membuka long dengan leverage 10x, kondisi seperti ini adalah alasan untuk memperkecil ukuran posisi dan memasang stop loss, karena koreksi 10% saja sudah cukup untuk menghabiskan margin Anda. Indeks tidak mengatakan harga akan turun, tetapi mengingatkan bahwa pasar sedang ramai.","mistakes":["Membeli otomatis setiap kali indeks menunjukkan ketakutan ekstrem tanpa rencana manajemen risiko.","Menganggap indeks dari penyedia berbeda memakai rumus yang sama.","Mengabaikan bahwa sentimen ekstrem bisa bertahan lama."],"faq":[{"q":"Apakah Fear and Greed Index akurat?","a":"Indeks ini akurat menggambarkan suasana pasar berdasarkan rumusnya, tetapi tidak dirancang untuk memprediksi harga. Nilainya paling berguna sebagai pengingat untuk mengendalikan emosi."},{"q":"Berapa angka Fear and Greed yang dianggap ekstrem?","a":"Umumnya di bawah 25 dianggap ketakutan ekstrem dan di atas 75 keserakahan ekstrem. Batas pastinya bisa sedikit berbeda antarpenyedia."}],"title":"Apa itu Fear and Greed Index kripto? Cara membacanya","description":"Pahami Fear and Greed Index: skala 0-100, faktor yang dihitung, dan cara memakainya tanpa menjadikannya sinyal beli-jual.","related":[["fomo","FOMO (fear of missing out)","FOMO atau fear of missing out adalah rasa takut ketinggalan keuntungan yang mendorong trader membeli secara impulsif setelah harga sudah naik tajam."],["fud","FUD (fear, uncertainty, doubt)","FUD adalah singkatan dari fear, uncertainty, and doubt, yaitu informasi atau rumor negatif yang menimbulkan rasa takut dan ragu sehingga mendorong orang menjual aset."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"referral-code":{"slug":"referral-code","cat":"exchange-features","en":"Referral code (fee rebate)","contentLocale":"id","term":"Kode referral (rebate biaya)","aka":["referral code","kode referal","kode undangan","fee rebate"],"short":"Kode referral adalah kode undangan yang Anda masukkan saat mendaftar di bursa kripto, yang dapat memberi Anda potongan atau pengembalian sebagian biaya trading (rebate) sesuai program bursa tersebut.","body":[["Bursa memakai program referral untuk menarik pengguna baru. Pengundang mendapat komisi dari ",["biaya trading","maker-taker-fees"]," pengguna yang diundang, dan sebagian program membagi komisi itu kembali kepada pengguna baru sebagai rebate atau diskon biaya. Besaran, durasi, dan produk yang berlaku berbeda di setiap bursa."],"Hal penting: kode referral umumnya hanya bisa dimasukkan saat pendaftaran. Jika Anda sudah punya akun tanpa kode, biasanya tidak bisa ditambahkan belakangan. Rebate bisa dibayar otomatis setiap hari atau minggu, atau harus diklaim, tergantung programnya.","Pakai kode dari sumber yang jelas dan daftar hanya di situs atau aplikasi resmi bursa. Waspadai tautan pendaftaran palsu yang meniru tampilan bursa untuk mencuri data login. Kode referral tidak mengubah keamanan akun atau hak Anda sebagai nasabah."],"example":["Misalkan Anda trading futures dengan volume 200.000 ",["USDT","usdt"]," per bulan dan biaya taker rata-rata 0,05%. Biaya bulanan Anda 100 USDT. Jika program referral mengembalikan 20% dari biaya itu, Anda menerima 20 USDT per bulan, atau 240 USDT per tahun dengan volume yang sama. Untuk trader dengan volume 10.000 USDT per bulan, biaya hanya 5 USDT dan rebate 1 USDT. Jadi manfaat rebate sangat bergantung pada seberapa sering dan seberapa besar Anda bertransaksi."],"mistakes":["Mendaftar dulu lalu baru mencari kode referral, padahal kode harus dimasukkan saat pendaftaran.","Mendaftar lewat tautan referral yang mengarah ke situs palsu.","Menaikkan frekuensi trading hanya demi mengejar rebate."],"faq":[{"q":"Apakah kode referral bisa dimasukkan setelah daftar?","a":"Di kebanyakan bursa tidak bisa, karena kode diikat ke akun saat pendaftaran. Beberapa bursa memberi jendela waktu singkat, jadi cek kebijakan bursa yang Anda pakai."},{"q":"Apakah memakai kode referral merugikan saya?","a":"Tidak, biaya trading Anda tidak naik karena kode referral. Komisi pengundang berasal dari bagian biaya milik bursa."}],"title":"Apa itu kode referral bursa kripto? Rebate biaya","description":"Pahami cara kerja kode referral dan rebate biaya trading di bursa kripto, cara menghitung manfaatnya, dan modus situs palsu.","related":[["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."],["vip-tier","Level VIP (tingkat biaya VIP)","Level VIP adalah tingkatan biaya trading di bursa kripto yang ditentukan oleh volume perdagangan 30 hari, saldo aset, atau kepemilikan token bursa, di mana level lebih tinggi mendapat biaya maker dan taker lebih rendah."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."]],"lesson":null,"coin":null,"tool":"/rates","cta":true},"tokenized-treasuries":{"slug":"tokenized-treasuries","cat":"tokenized-assets","en":"Tokenized treasuries","contentLocale":"id","term":"Obligasi pemerintah tokenisasi (tokenized treasuries)","aka":["tokenized treasuries","T-bills tokenisasi","obligasi tokenisasi"],"short":"Obligasi pemerintah tokenisasi adalah token blockchain yang didukung surat utang pemerintah, umumnya US Treasury bills jangka pendek, sehingga pemegangnya mendapat imbal hasil mirip bunga obligasi.","body":["Penerbit atau dana investasi membeli surat utang pemerintah AS, menyimpannya di kustodian, lalu menerbitkan token. Imbal hasil dibayarkan dengan menambah jumlah token, menaikkan harga token, atau pembagian berkala, tergantung desain produknya. BlackRock, Franklin Templeton, dan Ondo Finance termasuk nama yang dikenal di sektor ini.",["Berbeda dengan ",["stablecoin","stablecoin"],", yang umumnya tidak memberi bunga kepada pemegangnya, token obligasi meneruskan imbal hasil ke investor. Karena itu produk ini sering diperlakukan sebagai sekuritas, sehingga banyak yang mewajibkan ",["KYC","kyc"],", punya minimum investasi, dan hanya tersedia bagi investor yang memenuhi syarat di wilayah tertentu."],["Imbal hasilnya mengikuti suku bunga, sehingga akan turun jika bank sentral menurunkan suku bunga. Risiko lain meliputi risiko penerbit dan kustodian, jadwal penebusan, dan risiko ",["smart contract","smart-contract"],". Cek juga apakah ada biaya pengelolaan yang mengurangi imbal hasil bersih."]],"example":["Misalkan Anda menyimpan 10.000 ",["USDC","usdc"]," di token obligasi dengan imbal hasil 4,5% per tahun dan biaya 0,2%. Imbal hasil bersihnya 4,3%, atau sekitar 430 USDC per tahun, kira-kira 35,8 USDC per bulan. Jika setelah enam bulan suku bunga turun sehingga imbal hasil kotor menjadi 3,5%, maka bersihnya 3,3%. Hasil setahun menjadi sekitar 215 di paruh pertama ditambah 165 di paruh kedua, total 380 USDC. Angka ini tidak tetap seperti deposito berjangka."],"mistakes":["Menganggap token obligasi sama dengan stablecoin biasa.","Mengira imbal hasilnya tetap padahal mengikuti suku bunga.","Membeli token tiruan yang mengaku didukung obligasi tanpa bukti cadangan yang jelas."],"faq":[{"q":"Apakah token obligasi pemerintah aman?","a":"Aset dasarnya, surat utang pemerintah AS jangka pendek, tergolong berisiko rendah. Namun Anda tetap menanggung risiko penerbit, kustodian, smart contract, dan aturan penebusan."},{"q":"Kenapa token obligasi butuh KYC?","a":"Karena banyak produk ini diperlakukan sebagai sekuritas di bawah aturan pasar modal. Penerbit wajib memastikan investor memenuhi syarat dan tidak berasal dari wilayah terlarang."}],"title":"Apa itu tokenized treasuries? Obligasi di blockchain","description":"Pahami obligasi pemerintah tokenisasi: cara imbal hasil dibayar, bedanya dengan stablecoin, syarat KYC, dan risikonya.","related":[["real-world-assets","Real World Assets (RWA, aset dunia nyata)","Real World Assets (RWA) adalah aset dari dunia keuangan nyata, seperti surat utang negara, kredit, properti, emas, atau saham, yang kepemilikannya direpresentasikan sebagai token di blockchain."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama."],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-treasuries","cta":false}});
